import io, os, glob

HERE = os.path.dirname(os.path.abspath(__file__))
REPO = os.path.dirname(HERE)
SRC = os.path.join(REPO, 'game', 'contra')
OUT = os.path.join(HERE, 'contra_build.sh')

HEAD = r'''#!/bin/bash
# contra_build.sh - AUTO-GENERATED by compose_contra.py. Edit game/contra/*.cs, re-run composer; never hand-edit.
set -e
UNITY=/content/ue/Editor/Unity
DEMO=/content/work/demo
PROJ=/content/work/runandgun
BUNDLE=$PROJ/Builds/WebGL/probe

echo "=== PREFLIGHT ==="
test -f /content/unity_bin.txt || { echo NO_UNITY_BIN; exit 6; }
test -x "$UNITY" || { echo NO_EDITOR_BIN; exit 6; }
echo PREFLIGHT_OK

echo "=== PROJECT ==="
if [ ! -d "$PROJ/Assets" ]; then
  if [ -d "$DEMO/Assets" ]; then
    echo CLONE_FROM_DEMO
    rm -rf "$PROJ"
    cp -a "$DEMO" "$PROJ"
  else
    echo CREATE_PROJECT_FRESH
    rm -rf "$PROJ"
    "$UNITY" -batchmode -quit -nographics -createProject "$PROJ" -logFile /content/create_rag.log
    echo CREATE_DONE
  fi
fi
rm -rf "$PROJ/Assets/Demo" "$PROJ/Assets/Scenes" "$PROJ/Builds" "$PROJ/Temp"
test -d "$PROJ/Assets" || { echo NO_PROJECT; exit 6; }
mkdir -p "$PROJ/Assets/Editor" "$PROJ/Assets/Contra"

echo "=== ENSURE UGUI (bare -createProject lacks UnityEngine.UI) ==="
python3 - "$PROJ" <<'PYEOF'
import json, sys, os
p = os.path.join(sys.argv[1], 'Packages', 'manifest.json')
m = json.load(open(p))
m.setdefault('dependencies', {})
if 'com.unity.ugui' not in m['dependencies']:
    m['dependencies']['com.unity.ugui'] = '2.0.0'
    open(p, 'w').write(json.dumps(m, indent=2))
    print('UGUI_ADDED')
else:
    print('UGUI_PRESENT')
PYEOF
echo PROJECT_READY
'''

TAIL = r'''
echo "=== BUILD WEBGL ==="
rm -rf "$PROJ/Temp"
mkdir -p /tmp/xdg; chmod 700 /tmp/xdg
printf 'pcm.!default { type null }\nctl.!default { type null }\n' > /etc/asound.conf
export XDG_RUNTIME_DIR=/tmp/xdg
cd "$PROJ"
/usr/bin/time -v "$UNITY" -batchmode -nographics -quit -projectPath "$PROJ" -executeMethod BuildScript.PerformBuild -logFile /content/build_contra.log 2>/content/time_contra.txt
RC=$?
echo "BUILD_RC=$RC"
grep -E 'Elapsed|Maximum resident' /content/time_contra.txt || true
tail -8 /content/build_contra.log
test "$RC" = 0 || { echo BUILD_FAILED; exit 6; }
test -f "$BUNDLE/index.html" || { echo NO_BUNDLE_OUT; exit 6; }

echo "=== STAGE ==="
DST=/content/drive/MyDrive/unity-lab/pages-staging/webgl
rm -rf "$DST"
mkdir -p "$DST"
cp -a "$BUNDLE/." "$DST/"
echo STAGED_FILES=$(ls "$DST" | wc -l)
du -sh "$DST"
echo CONTRA_STAGED_OK
'''

parts = [HEAD]
cs_files = sorted(glob.glob(os.path.join(SRC, '*.cs')))
assert cs_files, 'no .cs files in ' + SRC
for path in cs_files:
    fname = os.path.basename(path)
    body = io.open(path, encoding='utf-8').read().rstrip('\n')
    assert '\\' not in body, 'BACKSLASH FOUND in ' + fname + ' (zero-backslash rule)'
    assert 'CSEOF' not in body, 'marker collision in ' + fname
    dest = 'Editor/BuildScript.cs' if fname == 'BuildScript.cs' else 'Contra/' + fname
    parts.append('cat > "$PROJ/Assets/%s" <<\'CSEOF\'\n%s\nCSEOF\n' % (dest, body))
    print('embedded: %-16s -> Assets/%s (%d chars)' % (fname, dest, len(body)))
parts.append(TAIL)
job = '\n'.join(parts)
io.open(OUT, 'w', encoding='utf-8', newline='\n').write(job)
print('WROTE', OUT, len(job), 'chars,', len(cs_files), 'scripts')
